#!/usr/bin/env python3
import json
import time
from pathlib import Path

ROOT = Path("/sys/devices/system/cpu/cpufreq")


def read_text(path):
    try:
        return path.read_text(encoding="ascii").strip()
    except OSError:
        return None


sample_epoch = int(time.time())
for policy_dir in sorted(ROOT.glob("policy[0-9]*")):
    total_text = read_text(policy_dir / "stats" / "total_trans")
    try:
        total_trans = int(total_text)
    except (TypeError, ValueError):
        continue

    event = {
        "sample_epoch": sample_epoch,
        "policy": policy_dir.name,
        "total_trans": total_trans,
    }
    for field in (
        "affected_cpus",
        "related_cpus",
        "scaling_driver",
        "scaling_governor",
    ):
        value = read_text(policy_dir / field)
        if value is not None:
            event[field] = value

    current_text = read_text(policy_dir / "scaling_cur_freq")
    try:
        event["current_frequency_khz"] = int(current_text)
    except (TypeError, ValueError):
        pass

    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)
